void irq_unlock(unsigned key) { enabled=key; }
void initialize(void) { c=d=k=l=r=bad=0;enabled=1;uart.user_cb=old_callback;uart.user_data=&old_data; }
void device_irq(void) { uart.user_cb(&dev,uart.user_data); }

static void uart_stm32_irq_callback_set(const struct device *dev,
					uart_irq_callback_user_data_t cb,
					void *cb_data)
{
	struct uart_stm32_data *data = dev->data;

	STEP(0, { data->user_cb=cb; });
	STEP(1, { data->user_data=cb_data; });

#if defined(CONFIG_UART_EXCLUSIVE_API_CALLBACKS)
	data->async_cb = NULL;
